fn run(terminal: &mut ratatui::DefaultTerminal, app: &mut App) -> std::io::Result<()> {
    loop {
        terminal.draw(|frame| draw(frame, app))?;

        if event::poll(Duration::from_millis(50))?
            && let CtEvent::Key(key) = event::read()?
                && key.kind == KeyEventKind::Press && !handle_key(app, key.code, key.modifiers) {
                    return Ok(());
                }

        while let Ok(update) = app.worker.updates.try_recv() {
            match update {
                Update::Delta(delta) => app.streaming.push_str(&delta),
                Update::Done { cost } => {
                    let text = std::mem::take(&mut app.streaming);
                    if !text.trim().is_empty() {
                        app.client.dispatch(Action::Append(format!("{text}\n\n")));
                    }
                    app.cost += cost;
                    app.status = format!("{:.4} usd", app.cost);
                }
                Update::Failed(err) => {
                    app.streaming.clear();
                    app.status = err;
                }
            }
        }
    }
}


