fn draw(frame: &mut Frame, app: &mut App) {
    let view = app.client.view();
    let area = frame.area();
    let [header, main, input_row, hint_row] = Layout::vertical([
        Constraint::Length(1),
        Constraint::Min(0),
        Constraint::Length(1),
        Constraint::Length(1),
    ])
    .areas(area);

    draw_header(frame, header, &view, app);

    let width = area.width.saturating_sub(8).min(110).max(20);
    let column = Rect {
        x: area.x + (area.width.saturating_sub(width)) / 2,
        y: main.y,
        width,
        height: main.height,
    };
    draw_transcript(frame, column, &view, app);

    if app.input.is_empty() {
        frame.render_widget(
            Paragraph::new(Line::from(vec![
                Span::styled("❯ ", Style::new().fg(ACCENT)),
                Span::styled("ask anything", Style::new().fg(DIM)),
            ])),
            input_row,
        );
        frame.set_cursor_position((input_row.x + 2, input_row.y));
    } else {
        frame.render_widget(
            Paragraph::new(Line::from(vec![
                Span::styled("❯ ", Style::new().fg(ACCENT)),
                Span::styled(app.input.clone(), Style::new().fg(TEXT)),
            ])),
            input_row,
        );
        frame.set_cursor_position(((input_row.x + 2 + app.input.len() as u16).min(input_row.right().saturating_sub(1)), input_row.y));
    }

    let hints = match app.mode {
        Mode::Picker => HINTS_PICKER,
        Mode::Chat if !app.input.is_empty() => HINTS_TYPING,
        Mode::Chat => HINTS_IDLE,
    };
    frame.render_widget(
        Paragraph::new(hints).style(Style::new().fg(DIM)),
        hint_row,
    );

    if app.mode == Mode::Picker {
        draw_picker(frame, area, &view, app.picker);
    }
}

fn draw_header(frame: &mut Frame, area: Rect, view: &View, app: &App) {
    let title = view
        .rows
        .iter()
        .find(|row| row.selected)
        .map(|row| row.text.clone())
        .unwrap_or_else(|| "no session".into());
    frame.render_widget(
        Paragraph::new(Line::from(Span::styled(
            title,
            Style::new().fg(DIM).add_modifier(Modifier::BOLD),
        ))),
        area,
    );
    let state = if app.streaming.is_empty() { app.status.clone() } else { "streaming…".to_string() };
    frame.render_widget(
        Paragraph::new(state)
            .alignment(Alignment::Right)
            .style(Style::new().fg(DIM)),
        area,
    );
}
